#!/bin/bash
# The French's transition one-shots: enter the bar, leave the bar (composed), stairs down, stairs up.
# Needs clean/ (run make_clean.sh first). Writes out/transitions/. Temp wav is overwritten each time, never deleted here.
cd "$(dirname "$0")"; mkdir -p out/transitions; T=out/transitions/_t.wav
eval "$(grep -E "^STEREO=" polish.sh)"
lufs() { ffmpeg -hide_banner -i "$1" -af ebur128=peak=true -f null - 2>&1 | awk '/^ *I:/{i=$2} /^ *Peak:/{p=$2} END{print i, p}'; }
finish() { ffmpeg -y -hide_banner -loglevel error -i "$1" -filter_complex "[0:a]$STEREO[o]" -map "[o]" -c:a pcm_f32le out/transitions/_s.wav; read cur pk < <(lufs out/transitions/_s.wav); g=$(echo "$2 - $cur" | bc -l); ffmpeg -y -hide_banner -loglevel error -i out/transitions/_s.wav -af "volume=${g}dB,alimiter=limit=-1.5dB:attack=5:release=80:level=false" -c:a aac_at -b:a 128k -movflags +faststart "$3"; read fi fp < <(lufs "$3"); d=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$3"); printf "%-24s %6.2fs  I=%s LUFS peak=%s dBFS\n" "$(basename "$3")" "$d" "$fi" "$fp"; }
cutter() { ffmpeg -y -hide_banner -loglevel error -i "clean/$1.wav" -af "atrim=start=$2:end=$3,asetpts=PTS-STARTPTS,afade=t=in:d=$4,afade=t=out:st=$(echo "$3 - $2 - $5" | bc -l):d=$5" -c:a pcm_f32le "$T"; finish "$T" "$6" "out/transitions/$7"; }
# into the bar, composed (2026-10-18, Sam: the continuous take was "much less clear" than the composed out): the pavement (rec144 77-80) -> the gents door at 20.04 s of the walk -> the bar at its loudest (rec143 29-34)
ffmpeg -y -hide_banner -loglevel error -i clean/rec144_OUTS.wav -i clean/rec145_GENTS.wav -i clean/rec143_BAR.wav -filter_complex "[0:a]atrim=start=78.5:end=80.1,asetpts=PTS-STARTPTS,afade=t=in:d=0.3[out];[1:a]atrim=start=19.9:end=20.7,asetpts=PTS-STARTPTS,volume=1.0[door];[2:a]atrim=start=29:end=34.5,asetpts=PTS-STARTPTS,afade=t=out:st=4.3:d=1.2[in];[out][door]acrossfade=d=0.15:c1=tri:c2=tri[a];[a][in]acrossfade=d=0.3:c1=qsin:c2=qsin[o]" -map "[o]" -c:a pcm_f32le "$T" && finish "$T" -30.0 out/transitions/french-enter-bar.m4a
cutter rec145_GENTS  8.4  18.0 0.3 0.8 -30.0 french-stairs-down.m4a   # down the stairs, footfalls at 9 and 14-16 s (2026-10-18: the bar seconds before cut, Sam heard the interior linger in the street)
cutter rec145_GENTS 91.0 103.5 0.4 1.2 -30.0 french-stairs-up.m4a     # up the stairs, into the bar by 102 s
# leave the bar, composed: inside (rec143 71-75) -> the gents door (rec145 65.6-67.0) -> outside (rec144 10-17)
ffmpeg -y -hide_banner -loglevel error -i clean/rec143_BAR.wav -i clean/rec145_GENTS.wav -i clean/rec144_OUTS.wav -filter_complex "[0:a]atrim=start=74.1:end=75.2,asetpts=PTS-STARTPTS,afade=t=in:d=0.3[in];[1:a]atrim=start=65.55:end=67.0,asetpts=PTS-STARTPTS,volume=0.9[door];[2:a]atrim=start=10:end=17,asetpts=PTS-STARTPTS,afade=t=out:st=5.8:d=1.2[out];[in][door]acrossfade=d=0.35:c1=tri:c2=tri[a];[a][out]acrossfade=d=0.9:c1=qsin:c2=qsin[o]" -map "[o]" -c:a pcm_f32le "$T" && finish "$T" -30.0 out/transitions/french-leave-bar.m4a
